from taf.sbts.oam.coam.admin.interfaces.admin_23r3 import SBTS23R3
from taf.sbts.oam.coam.admin.utils import raise_value_error
from taf.sbts.oam.coam.admin.utils.validators import ObjectValidator
from taf.sbts.oam.coam.admin.utils.util import wrap_result
from taf.sbts.oam.coam.admin.schemas.procedure.ccm_uplink_pusch_23r4 import CCMUplinkPusch


class SBTS23R4(SBTS23R3):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS23R4, self).__init__(api_client)

    def start_5g_uplink_ccm_test_pusch(self, dist_name, interval, beam_pattern_id,
                                       frc_index, prb_offset, digital_out_type,
                                       digital_out_rate, ul_dmrs_mapping_type, is_ptrs_fr2_enabled,
                                       ru_mode, phys_cell_id,
                                       bb_selector=None, nrarfcn_ul=None, nrarfcn_dl=None, num_uci_bits=None,
                                       csi_payload_bit=None, act_high_speed_cell=None, digital_output_enable=None,
                                       timeout=60):
        """
        Starts 5G `Pusch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param str frc_index: One of the following:
                                'G_FR1_A3_8' | 'G_FR1_A3_9' | 'G_FR1_A3_10' | 'G_FR1_A3_12' | 'G_FR1_A3_13' | 'G_FR1_A3_14' |
                                'G_FR1_A3_22' | 'G_FR1_A3_23' | 'G_FR1_A3_24' | 'G_FR1_A3_26' | 'G_FR1_A3_27' | 'G_FR1_A3_28' |
                                'G_FR1_A3_31' | 'G_FR1_A3_32' | 'G_FR1_A4_8' | 'G_FR1_A4_9' | 'G_FR1_A4_10' | G_FR1_A4_11 |
                                'G_FR1_A4_12' | 'G_FR1_A4_13' | 'G_FR1_A4_14' | 'G_FR1_A4_22' | 'G_FR1_A4_23' | 'G_FR1_A4_24' |
                                'G_FR1_A4_26' | 'G_FR1_A4_27' | 'G_FR1_A4_28' | 'G_FR1_A5_8' | 'G_FR1_A5_9' | 'G_FR1_A5_10' |
                                'G_FR1_A5_12' | 'G_FR1_A5_13' | 'G_FR1_A5_14' | 'G_FR2_A3_4' | 'G_FR2_A3_9' | 'G_FR2_A3_16' |
                                'G_FR2_A3_21' | 'G_FR2_A4_4' | 'G_FR2_A4_9' | 'G_FR2_A4_14' | 'G_FR2_A4_19' | 'G_FR2_A5_4' |
                                'G_FR2_A5_9' | 'G_FR1_A1_2' | 'G_FR1_A1_5' | 'G_FR1_A2_5' | 'G_FR1_A1_1' | 'G_FR1_A1_4' |
                                'G_FR1_A2_4' | 'G_FR1_A4_31' | 'G_FR1_A4_31A' | 'G_FR1_A4_32' | 'G_FR1_A4_32A' |
                                'G_FR1_A3_34' | 'G_FR1_A4_30' | 'G_FR2_A7_4' | 'G_FR2_A7_9' | 'G_FR1_A3_34A' | 'G_FR1_A4_30A'
                                'G_FR1_A3_11'| 'G_FR1_A3_25'| 'G_FR1_A4_25'| 'G_FR1_A5_11' | 'G_FR1_A2_2' |
                                'G_FR1_A9_1' | 'G_FR1_A9_2' | 'G_FR1_A9_3' | 'G_FR1_A9_4' | 'G_FR1_A9_5'
        :param int prb_offset: [0..273].
        :param str digital_out_type: Either `SerialKeysight` or `SerialRs`.
        :param str digital_out_rate: Either `Bitrate_115dot2K`,
                                     `Bitrate_1dot92M` or `Bitrate_460dot8K`.
        :param str ul_dmrs_mapping_type: "A" or "B".
        :param bool is_ptrs_fr2_enabled.
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param bool act_high_speed_cell: (optional) Activate high speed cell.
        :param bool digital_output_enable: Enable digital output.
        :param int bb_selector: (Optional) [0..3].
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param int num_uci_bits: (Optional) [0.255].
        :param list[int] csi_payload_bit: (Optional, two items at most) list of integers [0..4294967295]
        :param int timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::
            {
                "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
                "confirmationNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                    "parameters": {}
                },
                "resultNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                    "parameters": {
                        "status": "Succeeded"
                    }
                }
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        if not isinstance(is_ptrs_fr2_enabled, bool):
            raise ValueError('Parameter is_ptrs_fr2_enabled should be bool True or False not {}'
                             .format(type(is_ptrs_fr2_enabled)))
        if not isinstance(act_high_speed_cell, (bool, type(None))):
            raise ValueError('Parameter act_high_speed_cell should be bool True or False not {}'
                             .format(type(act_high_speed_cell)))
        if not isinstance(digital_output_enable, bool):
            raise ValueError('Parameter digital_output_enable should be bool True or False not {}'
                             .format(type(digital_output_enable)))

        PERFORMANCE_TEST_TYPE = "Pusch"
        pusch_schema = CCMUplinkPusch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, performance_test_type=PERFORMANCE_TEST_TYPE,
                                      frc_index=frc_index, prb_offset=prb_offset, digital_out_type=digital_out_type,
                                      digital_out_rate=digital_out_rate, ul_dmrs_mapping_type=ul_dmrs_mapping_type,
                                      is_ptrs_fr2_enabled=is_ptrs_fr2_enabled, ru_mode=ru_mode,
                                      phys_cell_id=phys_cell_id, bb_selector=bb_selector, nrarfcn_dl=nrarfcn_dl,
                                      num_uci_bits=num_uci_bits, csi_payload_bit=csi_payload_bit,
                                      act_high_speed_cell=act_high_speed_cell, digital_output_enable=digital_output_enable)
        parameters = pusch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

    def close_netconf_radio_session(self, target_distname, timeout=60, detailed_output=False):
        """
        Close Netconf radio session.

        :param string target_distname: Dist names for the objects to be closed.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-closeNetconfRadioSession.html
        """
        response = self._api_client.execute_customer_procedure("closeNetconfRadioSession",
                                                               {'targetDN': target_distname},
                                                               timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_netconf_radio_sessions(self, output_file_name, timeout=60, detailed_output=False):
        """
        Get Netconf radio sessions as a JSON file.

        :param string output_file_name: Path to a file.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getNetconfRadioSessions.html
        """
        response = self._api_client.execute_customer_procedure("getNetconfRadioSessions", {}, timeout,
                                                               output_file_name=output_file_name)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def query_netconf_radio_accounts(self, target_distnames, timeout=60, detailed_output=False):
        """
        Query Netconf radio accounts.

        :param list target_distnames: List of oru radio DN.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-queryNetconfRadioAccounts.html
        """
        response = self._api_client.execute_customer_procedure("queryNetconfRadioAccounts",
                                                               {'targetDNs': target_distnames},
                                                               timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def check_if_(self, class_name, id, parameters=None, timeout=10):
        """
        Assert that item exists and matches given parameters.

        :param string class_name: "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                                  "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS"
        :param string id: item ID
        :param string parameters: Required item parameters. None means no parameter value validation.
        :param int timeout: Time to wait for matching item.

        :return dict: dict with class name info

        More info at https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-subscribeForParameters.html
        """
        class_name = class_name.upper()
        if class_name not in ("RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                              "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                              "CABINET", "CARRIERGROUPC", "FHS"):
            raise_value_error(param="class_name",
                              value=str(class_name),
                              subpage="tutorial-subscribeForParameters.html")
        return self._api_client.execute_infomodel_subscription(
            "subscribeForParameters", {"className": class_name, "id": id}, ObjectValidator(parameters), timeout)

    @wrap_result
    def get_parameters_for(self, class_name, id_num, timeout=10):
        """
        Get parameters for sigle item.

        :param str class_name: "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                                  "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS"
        :param str id_num: item id_num
        :param int timeout: Time to wait for positive procedure result.

        :return AdminApiObject: Item parameters object

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getParametersForEntity.html
        """

        class_name = class_name.upper()
        if class_name not in ("RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                              "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                              "CABINET", "CARRIERGROUPC", "FHS"):
            raise_value_error(param="class_name",
                              value=str(class_name),
                              subpage="tutorial-getParametersForEntity.html")

        return self._api_client.execute_infomodel_request("getParametersForEntity",
                                                          {"entityType": class_name, "id": id_num}, timeout)

